method rotate(a: array<int>, offset:int) returns (b: array<int> )
  requires 0<=offset
  ensures b.Length==a.Length
  ensures forall  i::0<=i<a.Length ==>  b[i]==a[(i+offset)%a.Length] && i != 0
{
  b:= new int[a.Length];
  var i:=0;
  while i<a.Length
    invariant 0<=i<=a.Length
    invariant forall j ::0<=j<i ==> b[j]==a[(j+offset)%a.Length]
  {
    b[i]:=a[(i+offset)%a.Length];
    i:=i+1;
  }
}

method rotate(a: array<int>, offset:int) returns (b: array<int> )
  requires 0<=offset
  ensures b.Length==a.Length
  ensures forall  i::0<=i<a.Length ==>  b[i]==a[(i+offset)%a.Length]
{
  b:= new int[a.Length];
  var i:=0;
  while i<a.Length
    invariant 0<=i<=a.Length
    invariant forall j ::0<=j<i ==> b[j]==a[(j+offset)%a.Length]
  {
    b[i]:=a[(i+offset)%a.Length];
    i:=i+1;
  }
}{"spec_element": "ensures",
 "proof_obligation": "bridge",
 "diagnosis": "The postcondition adds a spurious conjunct '&& i != 0' to the rotation property. For any non-empty array, i = 0 is in the quantifier's range, so the postcondition demands 0 != 0, which is false (counterexample: a.Length = 1, i = 0). The loop invariant together with the exit condition i == a.Length implies b[i] == a[(i+offset)%a.Length] for all i in range, but it cannot imply i != 0. The fix is to remove the bogus conjunct from the ensures clause."}

